<?php if(!$data['product']): ?><section class="page-intro shell"><span class="eyebrow">404 — NOT FOUND</span><h1>পণ্যটি খুঁজে পাওয়া যায়নি।</h1><a class="button button-green" href="/shop">দোকানে ফিরে যান</a></section><?php else: $product=$data['product'];$images=$product['images']?:[['image_url'=>asset('category-tech.jpg'),'alt_text'=>$product['name']]];$jsonLd=['@context'=>'https://schema.org','@type'=>'Product','name'=>(string)$product['name'],'description'=>(string)($product['short_description']??''),'image'=>array_map(static fn($image)=>$image['image_url'],$images),'sku'=>(string)($product['sku']??''),'offers'=>['@type'=>'Offer','priceCurrency'=>(string)$product['currency'],'price'=>(string)$product['price'],'availability'=>(int)$product['stock_quantity']>0?'https://schema.org/InStock':'https://schema.org/OutOfStock','url'=>app_url('/product/'.$product['slug'])]]; ?><script type="application/ld+json" nonce="<?= e($cspNonce) ?>"><?= json_encode($jsonLd,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script><section class="product-detail shell"><div class="detail-gallery"><div class="detail-main-image"><img src="<?= e($images[0]['image_url']) ?>" alt="<?= e($images[0]['alt_text']?:$product['name']) ?>" fetchpriority="high"></div><?php if(count($images)>1): ?><div class="detail-thumbnails"><?php foreach(array_slice($images,1,4) as $image): ?><img src="<?= e($image['image_url']) ?>" alt="<?= e($image['alt_text']?:$product['name']) ?>" loading="lazy"><?php endforeach; ?></div><?php endif; ?></div><div class="detail-copy"><span class="eyebrow"><?= e($product['category_name']??'ALLSTORE PICK') ?></span><h1><?= e($product['name']) ?></h1><?php if(!empty($product['brand_name'])): ?><p class="detail-brand"><?= e($product['brand_name']) ?></p><?php endif; ?><p class="detail-price"><?= e(format_price((float)$product['price'],$product['currency'])) ?><?php if(!empty($product['compare_at_price'])&&(float)$product['compare_at_price']>(float)$product['price']): ?><del><?= e(format_price((float)$product['compare_at_price'],$product['currency'])) ?></del><?php endif; ?></p><p class="stock-status"><?= (int)$product['stock_quantity']>0?'মজুতে আছে':'এই মুহূর্তে মজুতে নেই' ?><?php if((int)$product['stock_quantity']>0&& (int)$product['stock_quantity']<= (int)($product['low_stock_threshold']??0)): ?> · সীমিত মজুত<?php endif; ?></p><?php if(!empty($product['review_summary']['count'])): ?><p class="review-summary" aria-label="গড় rating"><?= number_format((float)$product['review_summary']['average'],1) ?> / 5 · <?= (int)$product['review_summary']['count'] ?>টি রিভিউ</p><?php endif; ?><p class="detail-description"><?= nl2br(e($product['description']??$product['short_description']??'')) ?></p><?php if(!empty($product['attributes'])): ?><dl class="attribute-list"><?php foreach($product['attributes'] as $attribute): ?><div><dt><?= e($attribute['name']) ?></dt><dd><?= e(is_scalar($attribute['value'])?(string)$attribute['value']:json_encode($attribute['value'],JSON_UNESCAPED_UNICODE)) ?> <?= e($attribute['unit']??'') ?></dd></div><?php endforeach; ?></dl><?php endif; ?><?php if(!empty($product['variants'])): ?><section class="variant-list"><h2>বিকল্প</h2><p class="form-hint">এই product-এ variant আছে। Variant-ভিত্তিক cart/stock selection না হওয়া পর্যন্ত variant product অর্ডার করা যাবে না—ভুল price/stock দেখানো হচ্ছে না।</p><?php foreach($product['variants'] as $variant): ?><div class="variant-row"><strong><?= e($variant['name']) ?></strong><span><?= e(format_price((float)($variant['price']??$product['price']),$product['currency'])) ?></span><span><?= (int)$variant['stock_quantity']>0?'মজুতে':'মজুত নেই' ?></span></div><?php endforeach; ?></section><?php elseif((int)$product['stock_quantity']>0): ?><form action="/cart/add" method="post" class="detail-form"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><label for="quantity">পরিমাণ</label><input id="quantity" type="number" name="quantity" value="1" min="1" max="<?= min(20,(int)$product['stock_quantity']) ?>"><button class="button button-green" type="submit">ব্যাগে যোগ করুন <span aria-hidden="true">→</span></button></form><?php endif; ?><?php if(!empty($data['account'])): ?><form action="/account/wishlist" method="post" class="wishlist-form"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><input type="hidden" name="return_to" value="<?= e('/product/'.$product['slug']) ?>"><button class="button button-outline" type="submit">♡ Wishlist-এ রাখুন</button></form><?php endif; ?><p class="detail-note">COD order submit করার সময় price ও stock database-এ আবার যাচাই হয়।</p></div></section><section class="section shell"><div class="section-heading"><div><span class="eyebrow">VERIFIED PURCHASE REVIEWS</span><h2>গ্রাহকের মতামত</h2></div></div><?php if(empty($product['reviews'])): ?><div class="empty-state"><p>এখনো প্রকাশিত review নেই। শুধু delivered order-এর ক্রেতারা review জমা দিতে পারেন; admin moderation-এর পরে প্রকাশ হয়।</p></div><?php else: ?><div class="review-list"><?php foreach($product['reviews'] as $review): ?><article class="panel"><p class="review-stars" aria-label="<?= (int)$review['rating'] ?> out of 5 stars"><?= str_repeat('★',(int)$review['rating']) ?><?= str_repeat('☆',5-(int)$review['rating']) ?></p><h3><?= e($review['title']??'Verified customer review') ?></h3><p><?= nl2br(e($review['body']??'')) ?></p><span class="muted"><?= e($review['display_name']) ?> · <?= e(date('d M Y',strtotime($review['created_at']))) ?></span></article><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?>
